// Generated by ChatGPT

import { useState, useEffect } from "react";
import "./LocationInput.css";

async function geocode(query) {
  if (!query) return [];

  const res = await fetch(
    `https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(
      query,
    )}&limit=5`,
  );

  const data = await res.json();

  return data.map((place) => ({
    name: place.display_name,
    lat: parseFloat(place.lat),
    lng: parseFloat(place.lon),
  }));
}

async function reverseGeocode(lat, lon) {
  if (!lat || !lon) return "";

  const res = await fetch(
    `https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lon}`,
  );

  const data = await res.json();

  return data.display_name || "";
}

function LocationInput({ lat, lon, required, onChange }) {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState([]);

  useEffect(() => {
    async function loadLocation() {
      if (lat && lon) {
        const name = await reverseGeocode(lat, lon);
        setQuery(name);
      }
    }

    loadLocation();
  }, [lat, lon]);

  async function handleChange(e) {
    const val = e.target.value;
    setQuery(val);

    if (!val) {
      setResults([]);
      return;
    }

    const places = await geocode(val);
    setResults(places);
  }

  return (
    <div className="location-input" style={{ position: "relative" }}>
      <input value={query} required={required} onChange={handleChange} />

      {results.length > 0 && (
        <div className="dropdown">
          {results.map((place, i) => (
            <div
              key={i}
              className="dropdown-item"
              onClick={() => {
                setQuery(place.name);
                setResults([]);

                onChange(place.lat, place.lng);
              }}
            >
              {place.name}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default LocationInput;
